class StatusTextIsPinned(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.mkdtemp()

    def tearDown(self):
        shutil.rmtree(self.tmp)

    def status(self, machine_id=None, **kw):
        cfg, ctl, vast, paralon, docker = build_scenario(self.tmp, **kw)
        out = []
        self.assertEqual(cmd_status(ctl, cfg, machine_id, out=out.append), 0)
        self.assertEqual(vast.writes + paralon.writes + docker.writes, [])
        return "\n".join(out)

    def test_all_machines(self):
        self.assertEqual(self.status(), EXPECTED_OK)

    def test_one_machine(self):
        self.assertEqual(self.status(222), EXPECTED_ONE)

    def test_vast_unreadable(self):
        self.assertEqual(self.status(vast_fail=True), EXPECTED_VAST_FAIL)

    def test_paralon_unreadable(self):
        self.assertEqual(self.status(paralon_fail=True), EXPECTED_PARALON_FAIL)

    def test_names(self):
        self.assertEqual(self.status(names=True), EXPECTED_NAMED)

    def test_machine_unreadable(self):
        self.assertEqual(self.status(docker_fail=True), EXPECTED_DOCKER_FAIL)


if __name__ == "__main__":
    unittest.main()
